{
  "schemaVersion": 2,
  "modelId": "noface",
  "capabilities": {"headControl": false, "bodyControl": false, "eyeBlink": false, "eyeSmile": false,
    "gazeControl": false, "mouthOpen": false, "mouthSmile": false, "browControl": false,
    "blush": false, "tear": false, "sweat": false, "breath": false},
  "parameterMap": {
    "headX":      {"target": "PARAM_ANGLE_X",    "mode": "set", "scale": 30, "min": -30, "max": 30},
    "eyeOpen":    {"target": "PARAM_EYE_L_OPEN", "mode": "set", "scale": 1,  "min": 0, "max": 1.2},
    "eyeBlinkL":  {"target": "PARAM_EYE_L_OPEN", "mode": "subtract", "scale": 1, "min": 0, "max": 1.2},
    "blush":      {"target": "PARAM_CHEEK",      "mode": "set", "scale": 1,  "min": 0, "max": 1},
    "tear":       {"target": "PARAM_TEAR",       "mode": "set", "scale": 1,  "min": 0, "max": 1},
    "sweat":      {"target": "PARAM_SWEAT",      "mode": "set", "scale": 1,  "min": 0, "max": 1}
  },
  "neutralParams": {"PARAM_ANGLE_X": 0, "PARAM_EYE_L_OPEN": 1, "PARAM_CHEEK": 0, "PARAM_TEAR": 0, "PARAM_SWEAT": 0}
}
